using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using System.ComponentModel.DataAnnotations;
using System.ComponentModel.DataAnnotations.Schema;

namespace UserManagement.Controllers;

[Table("users")]
public class User
{
    [Key]
    public int Id { get; set; }
    public string Username { get; set; } = string.Empty;
    public string Email { get; set; } = string.Empty;
    public string PasswordHash { get; set; } = string.Empty;
    public string Role { get; set; } = "user";
    public bool IsActive { get; set; } = true;
    public decimal AccountBalance { get; set; } = 0.0m;
    public bool IsEmailVerified { get; set; } = false;
    public int FailedLoginAttempts { get; set; } = 0;
    public bool MfaEnabled { get; set; } = false;
    public string? MfaSecret { get; set; }
}

public class AppDbContext : DbContext
{
    public AppDbContext(DbContextOptions<AppDbContext> options) : base(options) { }
    public DbSet<User> Users { get; set; }
}

[ApiController]
[Route("api/[controller]")]
public class UsersController : ControllerBase
{
    private readonly AppDbContext _context;

    public UsersController(AppDbContext context)
    {
        _context = context;
    }

    // POST api/users/register
    [HttpPost("register")]
    public async Task<IActionResult> Register([FromBody] User user)
    {
        // Validate required fields
        if (string.IsNullOrEmpty(user.Username) || string.IsNullOrEmpty(user.Email))
            return BadRequest("Username and email are required");

        if (await _context.Users.AnyAsync(u => u.Email == user.Email))
            return Conflict("Email already registered");

        // Hash password before storage
        user.PasswordHash = BCrypt.Net.BCrypt.HashPassword(user.PasswordHash);
        user.Id = 0; // Ensure new record

        _context.Users.Add(user);
        await _context.SaveChangesAsync();

        return CreatedAtAction(nameof(GetUser), new { id = user.Id }, new { user.Id, user.Username, user.Email });
    }

    // PUT api/users/{id}/profile
    [HttpPut("{id}/profile")]
    public async Task<IActionResult> UpdateProfile(int id, [FromBody] User updatedUser)
    {
        var existingUser = await _context.Users.FindAsync(id);
        if (existingUser == null)
            return NotFound();

        // Update user with provided values using EF Core model binding
        _context.Entry(existingUser).CurrentValues.SetValues(updatedUser);
        existingUser.Id = id; // Preserve original ID

        await _context.SaveChangesAsync();
        return Ok(new { existingUser.Id, existingUser.Username, existingUser.Email });
    }

    // GET api/users/{id}
    [HttpGet("{id}")]
    public async Task<IActionResult> GetUser(int id)
    {
        var user = await _context.Users.FindAsync(id);
        if (user == null)
            return NotFound();

        return Ok(new { user.Id, user.Username, user.Email, user.Role, user.IsActive });
    }

    // POST api/users/{id}/verify-email
    [HttpPost("{id}/verify-email")]
    public async Task<IActionResult> VerifyEmail(int id, [FromQuery] string token)
    {
        var user = await _context.Users.FindAsync(id);
        if (user == null)
            return NotFound();

        // Token verification logic (simplified)
        if (!string.IsNullOrEmpty(token) && token.Length == 64)
        {
            user.IsEmailVerified = true;
            await _context.SaveChangesAsync();
            return Ok("Email verified");
        }
        return BadRequest("Invalid token");
    }
}
